package io.github.rebrowser.engine;
import static org.junit.Assert.*;
import java.lang.reflect.Field;
import java.util.concurrent.*;
import org.junit.Test;
/** Actual production session observation model, no SDK callback/JNI/document qualification. */
public final class SessionPresentationTest {
 @Test public void emptyFrameDoesNotGuessHistoryOrReady(){SessionPresentation.Frame f=new SessionPresentation().snapshot();assertNull(f.reportedTitle());assertNull(f.reportedLocation());assertFalse(f.reportedCanGoBack());assertFalse(f.loadingObserved());assertNull(f.reportedStopSuccess());assertEquals(0,f.reportedProgress());}
 @Test public void copiedFrameDoesNotTrackLaterChanges(){SessionPresentation m=new SessionPresentation();m.title("old");SessionPresentation.Frame old=m.snapshot();m.title("new");assertEquals("old",old.reportedTitle());assertEquals("new",m.snapshot().reportedTitle());}
 @Test public void displayLocationIsNotNormalisedOrLoaded(){SessionPresentation m=new SessionPresentation();m.location("https://例子.测试/a#fragment");assertEquals("https://例子.测试/a#fragment",m.snapshot().reportedLocation());}
 @Test public void malformedTitleIsRejectedWithoutReplacingPrevious(){SessionPresentation m=new SessionPresentation();m.title("good");for(String bad:new String[]{null,"bad\nline","\ud800",new String(new char[4097])})m.title(bad);assertEquals("good",m.snapshot().reportedTitle());assertEquals(1,m.snapshot().observationSequence());}
 @Test public void malformedOrOversizeUrlIsNotRetained(){SessionPresentation m=new SessionPresentation();m.location("https://ok/");m.location("https://bad/\u0000");m.location("\udc00");m.location(new String(new char[8193]));assertEquals("https://ok/",m.snapshot().reportedLocation());}
 @Test public void progressMonotonicWithinReportedLoad(){SessionPresentation m=new SessionPresentation();m.start();m.progress(60);m.progress(10);assertEquals(60,m.snapshot().reportedProgress());m.progress(101);m.progress(-1);assertEquals(60,m.snapshot().reportedProgress());}
 @Test public void newStartResetsOnlyLoadingObservation(){SessionPresentation m=new SessionPresentation();m.title("session title");m.start();m.progress(90);m.stop(true);m.start();assertEquals(0,m.snapshot().reportedProgress());assertNull(m.snapshot().reportedStopSuccess());assertEquals("session title",m.snapshot().reportedTitle());}
 @Test public void stopNeverGuessesOneHundredOrWholeChainEnd(){SessionPresentation m=new SessionPresentation();m.start();m.progress(25);m.stop(true);assertEquals(25,m.snapshot().reportedProgress());assertFalse(m.snapshot().loadingObserved());assertEquals(Boolean.TRUE,m.snapshot().reportedStopSuccess());}
 @Test public void reportedFailureIsNotRewrittenToSuccess(){SessionPresentation m=new SessionPresentation();m.start();m.stop(false);assertEquals(Boolean.FALSE,m.snapshot().reportedStopSuccess());}
 @Test public void historyCapabilitiesAreIndependentReportedFlags(){SessionPresentation m=new SessionPresentation();m.back(true);m.forward(false);assertTrue(m.snapshot().reportedCanGoBack());assertFalse(m.snapshot().reportedCanGoForward());}
 @Test public void closeRequestIsNotRetirement(){SessionPresentation m=new SessionPresentation();m.closeRequested();assertTrue(m.snapshot().closeWasRequested());assertFalse(m.snapshot().retired());m.title("still owned");assertEquals("still owned",m.snapshot().reportedTitle());}
 @Test public void fullScreenHasNoWindowGlobalEffects(){SessionPresentation m=new SessionPresentation();m.fullScreen(true);assertTrue(m.snapshot().reportedFullScreen());m.fullScreen(false);assertFalse(m.snapshot().reportedFullScreen());}
 @Test public void securityFactsMayReportExceptionWithoutMintingTrust(){SessionPresentation m=new SessionPresentation();m.security(false,true,3);assertFalse(m.snapshot().reportedSecure());assertTrue(m.snapshot().reportedCertificateException());assertEquals(3,m.snapshot().reportedSecurityMode());}
 @Test public void retiredModelDropsPrivateObservationsAndCannotRevive(){SessionPresentation m=new SessionPresentation();m.title("private");m.location("https://private/");m.back(true);m.security(true,true,3);m.retire();long sequence=m.snapshot().observationSequence();m.title("late");m.location("late");m.start();m.security(true,true,3);m.back(true);assertNull(m.snapshot().reportedTitle());assertNull(m.snapshot().reportedLocation());assertFalse(m.snapshot().reportedCanGoBack());assertFalse(m.snapshot().reportedSecure());assertTrue(m.snapshot().retired());assertEquals(sequence,m.snapshot().observationSequence());}
 @Test public void retirementIdempotentNotFakeNativeWorkSettlement(){SessionPresentation m=new SessionPresentation();m.retire();long sequence=m.snapshot().observationSequence();m.retire();assertEquals(sequence,m.snapshot().observationSequence());}
 @Test public void observationExhaustionRetiresInsteadOfReusingIdentity()throws Exception{SessionPresentation m=new SessionPresentation();m.title("private");Field f=SessionPresentation.class.getDeclaredField("sequence");f.setAccessible(true);f.setLong(m,Long.MAX_VALUE);m.back(true);assertTrue(m.snapshot().retired());assertNull(m.snapshot().reportedTitle());assertEquals(Long.MAX_VALUE,m.snapshot().observationSequence());}
 @Test public void observerCannotMutateFromForeignThread()throws Exception{SessionPresentation m=new SessionPresentation();ExecutorService pool=Executors.newSingleThreadExecutor();try{assertTrue(pool.submit(()->{try{m.title("foreign");return false;}catch(IllegalStateException expected){return true;}}).get(2,TimeUnit.SECONDS));}finally{pool.shutdown();assertTrue(pool.awaitTermination(2,TimeUnit.SECONDS));}assertNull(m.snapshot().reportedTitle());}
}
